<script>
const csrf=document.querySelector('meta[name="csrf-token"]').content;
const variants=['hike','park','magog','abbey','cruise','spa'];
const labels={hike:'A · Wandern',park:'B · Park',magog:'C · Magog',abbey:'D · Abtei',cruise:'E · Schiff',spa:'F · Spa'};
let state=null;
async function api(method='GET',body=null){const o={method,headers:{'Accept':'application/json'}};if(body){o.headers['Content-Type']='application/json';o.headers['X-CSRF-Token']=csrf;o.body=JSON.stringify(body)}const r=await fetch('orford-activities-vote.php',o);const d=await r.json().catch(()=>({error:'Ungültige Serverantwort'}));if(!r.ok)throw new Error(d.error||'Speichern fehlgeschlagen');return d}
function esc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}
function stars(r,v){let h='<div class="stars">';for(let i=1;i<=5;i++)h+=`<button type="button" class="star-button ${i<=(r||0)?'active':''}" data-rate="${i}" data-variant="${v}" aria-label="${i} Sterne">★</button>`;return h+'</div>'}
function dateText(iso){try{return new Intl.DateTimeFormat('de-DE',{dateStyle:'short',timeStyle:'short'}).format(new Date(iso))}catch{return''}}
function commentHtml(c,view,reply){const deleted=!!c.deleted,name=deleted?'Gelöschter Kommentar':(view.profiles[c.profile]?.name||'Unbekannt'),canDelete=!deleted&&c.profile===view.currentProfile;const ra=!reply&&!deleted?`<button type="button" data-reply="${esc(c.id)}">Antworten</button>`:'',da=canDelete?`<button type="button" data-delete="${esc(c.id)}">Löschen</button>`:'',rf=!reply&&!deleted?`<form class="reply-form" data-parent="${esc(c.id)}" data-variant="${esc(view.variant)}"><input maxlength="1000" placeholder="Antwort schreiben …" required><button>Antworten</button></form>`:'';return `<div class="comment ${reply?'reply':''}"><div class="comment-head"><strong>${esc(name)}</strong><span>${esc(dateText(c.createdAt))}</span></div><p>${deleted?'Kommentar wurde gelöscht.':esc(c.text)}</p><div class="comment-actions">${ra}${da}</div>${rf}</div>`}
function renderOne(v){const view=state.variants[v];view.variant=v;document.getElementById('ratings-'+v).innerHTML=Object.entries(view.profiles).map(([id,p])=>`<div class="person-rating"><b>${esc(p.name)}</b>${id===view.currentProfile?stars(view.ratings[id]||0,v):`<span>${'★'.repeat(view.ratings[id]||0)}${'☆'.repeat(5-(view.ratings[id]||0))}</span>`}</div>`).join('');const roots=view.comments.filter(c=>!c.parentId);document.getElementById('comments-'+v).innerHTML=roots.length?roots.map(root=>commentHtml(root,view,false)+view.comments.filter(c=>c.parentId===root.id).map(r=>commentHtml(r,view,true)).join('')).join(''):'<div class="rating-help">Noch keine Kommentare.</div>';document.getElementById('avg-'+v).textContent=view.average===null?'–':`${view.average.toFixed(1)} / 5`}
function render(){variants.forEach(renderOne);const rated=variants.filter(v=>state.variants[v].average!==null).sort((a,b)=>state.variants[b].average-state.variants[a].average);document.getElementById('leader').textContent=rated.length?labels[rated[0]]:'noch offen'}
async function refresh(){state=await api();render()}
document.addEventListener('click',async e=>{const rate=e.target.closest('[data-rate]');if(rate){const v=rate.dataset.variant,s=document.getElementById('status-'+v);try{s.textContent='Speichere …';state=await api('POST',{action:'rating',variant:v,rating:Number(rate.dataset.rate)});render();s.textContent='Bewertung gespeichert.'}catch(err){s.textContent=err.message}return}const rep=e.target.closest('[data-reply]');if(rep){const f=document.querySelector(`.reply-form[data-parent="${CSS.escape(rep.dataset.reply)}"]`);if(f){f.classList.toggle('open');if(f.classList.contains('open'))f.querySelector('input').focus()}return}const del=e.target.closest('[data-delete]');if(del){if(!confirm('Eigenen Kommentar wirklich löschen?'))return;const v=del.closest('.vote-card').dataset.variant,s=document.getElementById('status-'+v);try{state=await api('POST',{action:'delete-comment',variant:v,commentId:del.dataset.delete});render();s.textContent='Kommentar gelöscht.'}catch(err){s.textContent=err.message}}});
document.addEventListener('submit',async e=>{if(e.target.matches('.comment-form')){e.preventDefault();const v=e.target.dataset.variant,i=e.target.querySelector('input'),s=document.getElementById('status-'+v);try{state=await api('POST',{action:'comment',variant:v,text:i.value});i.value='';render();s.textContent='Kommentar gespeichert.'}catch(err){s.textContent=err.message}}if(e.target.matches('.reply-form')){e.preventDefault();const v=e.target.dataset.variant,i=e.target.querySelector('input'),s=document.getElementById('status-'+v);try{state=await api('POST',{action:'comment',variant:v,text:i.value,parentId:e.target.dataset.parent});render();s.textContent='Antwort gespeichert.'}catch(err){s.textContent=err.message}}});
refresh().catch(err=>variants.forEach(v=>document.getElementById('status-'+v).textContent='Abstimmung konnte nicht geladen werden: '+err.message));
</script>
</body></html>
